'use strict';

const $=s=>document.querySelector(s), arr=v=>Array.isArray(v)?v:[], finite=v=>typeof v==='number'&&Number.isFinite(v);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const human=v=>String(v??'unreported').replaceAll('_',' '), number=(v,d=0)=>finite(v)?v.toLocaleString('en-GB',{maximumFractionDigits:d,minimumFractionDigits:d}):'Unknown';
const unique=v=>[...new Set(v.filter(x=>x!==null&&x!==undefined&&x!==''))];
const state={analysis:null,registers:[],acquisition:null,errors:[],config:{},query:'',medium:'all',council:'all',origin:'all',page:1,matrix:'whole',rowBlock:0,colBlock:0,pairKind:'cross',keyword:'',readingDimension:'contact_framing',sourceQuery:'',sourcePage:1,returnFocus:null};
const shades=['#f4f6ed','#d9e5d3','#b4ceac','#7da16f','#41633a'];

function url(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:null;}catch{return null;}}
function external(value,label='Open publisher source'){const href=url(value);return href?`<a href="${esc(href)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:'Source URL unreported';}
function date(value){if(!value)return 'Date unreported';const d=new Date(value);return Number.isFinite(d.getTime())?d.toLocaleString('en-GB',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'UTC'})+' UTC':String(value);}
function line(value){return Array.isArray(value)?value.map(human).join('; '):typeof value==='object'&&value!==null?Object.entries(value).map(([k,v])=>`${human(k)}: ${line(v)}`).join('; '):String(value??'Unreported');}
function announce(text){$('#live-status').textContent=text;}
function navCurrent(){const current=location.hash||'#overview';document.querySelectorAll('.view-nav a').forEach(a=>{if(a.getAttribute('href')===current)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});}
function docs(){return arr(state.analysis?.documents);}
function doc(id){return docs().find(d=>d.source_id===id);}
function label(d){return d.council_label_exact||d.claimed_label||'Exact label unreported';}
function medium(d){return d.medium||d.medium_label||d.medium_id||'Medium unreported';}
function textOrigin(d){return d.text_origin||'text origin unreported';}
function sourceId(s){return s.source_id||s.id;}
function sourceURL(s){return s?.canonical_url||s?.source_url||s?.url;}
function sources(){const all=state.registers.flatMap(r=>arr(r.sources));return [...new Map(all.filter(s=>sourceId(s)).map(s=>[sourceId(s),s])).values()];}
function source(id){const direct=sources().find(s=>sourceId(s)===id);if(direct)return direct;const binding=arr(state.acquisition?.records).find(r=>r.document_source_id===id&&r.primary_source_id),primary=doc(id)?.primary_source_id||binding?.primary_source_id;return primary?sources().find(s=>sourceId(s)===primary):undefined;}
function summaryText(value){return typeof value==='string'?value:line(value);}
function nameFindings(){return state.registers.flatMap(r=>arr(r.name_findings||r.identity_findings||r.query_findings));}
function facts(rows){return `<dl class="source-meta">${rows.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${v}</dd>`).join('')}</dl>`;}
function inspectButton(id,text,description){return `<button type="button" class="text-button" data-inspect="${esc(id)}" ${description?'aria-label="'+esc(description)+'"':''}>${esc(text||id)}</button>`;}

async function getJson(path){
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);
  try{const response=await fetch(path,{cache:'no-store',signal:controller.signal});if(!response.ok)throw Error(`The ${path} resource returned HTTP ${response.status}.`);const d=await response.json();if(!d||typeof d!=='object'||d.synthetic_fixture_run===true||d.is_fixture===true)throw Error(`The ${path} resource is not a supported observed-data release.`);return d;}
  finally{clearTimeout(timer);}
}

async function load(){
  $('#app').setAttribute('aria-busy','true');state.errors=[];state.registers=[];state.acquisition=null;
  try{
    state.config=JSON.parse($('#data-files').textContent);
    if(state.config.analysis!=='analysis.json'||arr(state.config.registers).some(x=>!['galactic-register.json','contact-register.json'].includes(x))||![null,undefined,'acquisition.json'].includes(state.config.acquisition))throw Error('The declared local data paths are unsupported.');
    state.analysis=await getJson(state.config.analysis);
    if(!Array.isArray(state.analysis.documents)||!state.analysis.coverage)throw Error('The released analysis is missing its source records or coverage.');
    if(new Set(docs().map(d=>d.source_id)).size!==docs().length||docs().some(d=>!d.source_id))throw Error('The analysis source identifiers are missing or duplicated.');
    if(finite(state.analysis.coverage.documents)&&state.analysis.coverage.documents!==docs().length)throw Error('The analysis document count does not match its records.');
    const results=await Promise.allSettled(arr(state.config.registers).map(getJson));
    results.forEach((r,i)=>r.status==='fulfilled'?state.registers.push({...r.value,_public_file:state.config.registers[i]}):state.errors.push(`Source register unavailable: ${state.config.registers[i]}. Analysis values remain the published snapshot.`));
    if(state.config.acquisition){try{state.acquisition=await getJson(state.config.acquisition);}catch{state.errors.push('Audio acquisition receipts could not be loaded. Audio counts are unknown; text-study counts remain available.');}}
    const params=new URLSearchParams(location.search);state.query=params.get('q')||'';state.medium=params.get('medium')||'all';state.council=params.get('council')||'all';state.origin=params.get('origin')||'all';
    render();$('.view-nav').hidden=false;navCurrent();announce('Council study loaded. Source records, text comparisons and collection status are available.');
  }catch(e){state.analysis=null;$('.view-nav').hidden=true;$('#app').innerHTML=`<section class="error-panel"><span class="eyebrow">RESEARCH DATA UNAVAILABLE</span><h1>Council study could not load.</h1><p>${esc(e.name==='AbortError'?'The data request timed out.':e.message)}</p><p>No example observations or replacement counts are shown. The earlier studies remain available.</p><button class="retry" id="retry-load" type="button">Retry loading</button><div class="json-links"><a href="../channeling-network/">Open earlier comparison dashboard</a><a href="analysis.json">Inspect the analysis JSON</a></div></section>`;announce('Council research data could not load. Retry is available.');}
  finally{$('#app').setAttribute('aria-busy','false');}
}

function render(){
  const a=state.analysis,c=a.coverage;
  $('#app').innerHTML=`<section id="overview" class="section"><div class="page-head"><div><span class="eyebrow">COUNCIL STUDY · SOURCES BEFORE SIMILARITIES</span><h1>Which council,<br>through whom?</h1><p>Compare the exact names used by publishers, the mediums associated with them, and the language in retained messages. Shared words guide discovery; each record preserves its exact source attribution.</p></div><aside class="cutoff"><strong>Inspected-source snapshot</strong><span>${esc(date(a.generated_at))}</span><p>${esc(a.scope||'A bounded publisher-source study; not a census of all council-related channeling or YouTube uploads.')}</p><a href="#messages">Explore the message records ↓</a></aside></div>
    ${state.errors.map(e=>`<div class="problem-note"><strong>Resource unavailable.</strong> ${esc(e)}</div>`).join('')}
    <div class="metrics" aria-label="Retained text study coverage"><div><b id="metric-documents">${number(docs().length)}</b><span>selected text units</span></div><div><b>${number(c.words??docs().reduce((n,d)=>n+(finite(d.words)?d.words:0),0))}</b><span>words in selected texts</span></div><div><b>${number(unique(docs().map(d=>d.medium_id||medium(d))).length)}</b><span>medium contexts represented</span></div><div><b>${number(unique(docs().map(label)).length)}</b><span>exact printed label strings</span></div></div>
    <div id="name-findings">${findingsView()}</div>${relationshipView()}<div class="claim-note"><p><strong>Contract and Contact remain different search terms.</strong> Their spelling is not normalized into one council. Named councils, broad “galactic” groupings and incidental mentions remain separate; contemporary publisher claims do not establish an external council or represent a religion's doctrine.</p></div>
    <h2 class="map-heading">From medium to printed name.</h2><p class="analysis-note">This map uses only the selected text records below. Identical printed names share a label node; that grouping does not authenticate a shared being. Line width reflects text count, not confidence.</p><div id="attribution-map">${mapView()}</div></section>
    <section class="section" id="messages"><div class="section-head"><div><span class="eyebrow">DOCUMENTS & EDITIONS</span><h2>Inspect what was actually retained.</h2></div><p>Filter by medium, exact printed label or text origin. Open a record for its source, word count, attribution and edition metadata.</p></div>${messageFilters()}<div id="message-results">${messageTable()}</div></section>
    <section class="section" id="comparison"><div class="section-head"><div><span class="eyebrow">EXPLORATORY TEXT COMPARISON</span><h2>Shared language, with context.</h2></div><p>Scores describe the released text representation. They are not probabilities of agreement, source independence or council identity.</p></div>${comparisonView()}</section>
    <section class="section" id="collection"><div class="section-head"><div><span class="eyebrow">RECORDINGS & TEXT COVERAGE</span><h2>Track audio and transcription.</h2></div><p>Previously retained recordings and newly downloaded files have separate counts. Written publisher messages belong to the text study and are not automatically aligned audio transcripts.</p></div>${collectionView()}</section>
    <section class="section" id="sources"><div class="section-head"><div><span class="eyebrow">METHODS, SOURCES & LIMITS</span><h2>Follow the evidence.</h2></div><p>Access depth, attribution support and collection cutoffs determine what each source can establish. No human accuracy or independent-origin verification is inferred from model agreement.</p></div>${methodsView()}<label class="keyword-tools">Find a research source<input id="source-query" type="search" placeholder="Publisher, title, URL or source ID" value="${esc(state.sourceQuery)}"></label><div id="source-results">${sourceList()}</div></section>`;
}

function findingsView(){
  const findings=nameFindings();
  if(!findings.length)return '<p class="empty">Exact-name findings are not supplied in the loaded source registers. Consult the inspected-source records below; absence here does not establish that a name is unused elsewhere.</p>';
  return `<div class="name-findings">${findings.map(f=>{const status=f.status||f.retrieval_status||'unreported',name=f.query||f.name||f.label||f.term||'Queried name',body=f.summary||f.finding||f.notes||f.interpretation||'';return `<article class="name-finding"><span class="status-label ${/unresolved|not|uncertain|unverified|lead|missing/i.test(status)?'uncertain':''}">${esc(human(status))}</span><h3>${esc(name)}</h3><p>${esc(summaryText(body))}</p><div class="sources">${arr(f.source_ids).map((id,i)=>inspectButton(id,`Inspect source ${i+1}`,`Inspect source ${i+1}: ${source(id)?.title||doc(id)?.title||id}`)).join('')}</div></article>`;}).join('')}</div>`;
}

function relationshipView(){
  const rows=state.registers.flatMap(reg=>arr(reg.relationships).map(r=>({...r,_medium:arr(reg.mediums).find(m=>(m.id||m.medium_id)===r.medium_id),_council:arr(reg.councils).find(c=>(c.id||c.council_id)===r.council_id)})));if(!rows.length)return '';
  return `<h2 class="map-heading">People, names & evidence types.</h2><p class="analysis-note">A publisher description, a retained message body and a search-only lead support different claims. This register includes discovery leads outside the selected text study. Linked study records use exact source IDs or explicit publisher-to-ASR source bindings declared by the analysis or acquisition receipts.</p><div class="table-wrap" role="region" tabindex="0" aria-label="Typed council attribution research register"><table class="relationship-table"><thead><tr><th>Person / publishing context</th><th>Exact source label</th><th>Attribution evidence</th><th>Source references / study links</th></tr></thead><tbody>${rows.map(r=>{const ids=arr(r.source_ids),matched=docs().filter(d=>ids.includes(d.source_id)),bound=docs().filter(d=>!ids.includes(d.source_id)&&(ids.includes(d.primary_source_id)||arr(state.acquisition?.records).some(a=>a.document_source_id===d.source_id&&ids.includes(a.primary_source_id))));return `<tr><th scope="row">${esc(r.medium_name||r.medium||r._medium?.name||r.medium_id||'Identity unresolved')}</th><td>${esc(r.council_label_exact||r.council_label||r._council?.label||'Exact label unreported')}</td><td>${esc(human(r.attribution_kind||r.relation_type||r.relationship_type||r.kind||'Type unreported'))}<small>${esc(summaryText(r.notes||r.evidence_level||''))}</small></td><td>${ids.map((id,i)=>inspectButton(id,`Source ${i+1}`,`Source ${i+1}: ${source(id)?.title||doc(id)?.title||id}`)).join(' ')}<small>${number(matched.length)} direct source-ID links · ${number(bound.length)} explicitly linked ASR editions</small>${bound.map(d=>inspectButton(d.source_id,'Inspect linked ASR edition','Inspect linked ASR edition: '+d.title)).join(' ')}</td></tr>`;}).join('')}</tbody></table></div>`;
}

function mapLabel(name,x,y,anchor='start',width=36){
  const lines=[];let current='';
  for(const word of String(name).split(' ')){if(current&&current.length+word.length+1>width){lines.push(current);current=word;}else current+=(current?' ':'')+word;}
  if(current)lines.push(current);
  const top=y-(lines.length-1)*7;
  return `<text class="map-label" x="${x}" y="${top}" text-anchor="${anchor}">${lines.map((l,i)=>`<tspan x="${x}" dy="${i?14:0}">${esc(l)}</tspan>`).join('')}</text>`;
}
function mapView(){
  const records=docs(),mediums=unique(records.map(d=>d.medium_id||medium(d))),labels=unique(records.map(label));
  if(!records.length)return '<p class="empty">No selected text records are available for an attribution map.</p>';
  const height=Math.max(250,60+Math.max(mediums.length,labels.length)*76),ys=(i,n)=>n===1?height/2:42+i*(height-84)/(n-1),edges=[];
  for(let i=0;i<mediums.length;i++)for(let j=0;j<labels.length;j++){const n=records.filter(d=>(d.medium_id||medium(d))===mediums[i]&&label(d)===labels[j]).length;if(n)edges.push(`<path class="map-edge" stroke-width="${Math.min(7,1.5+Math.log2(n+1))}" d="M290 ${ys(i,mediums.length)} C405 ${ys(i,mediums.length)},445 ${ys(j,labels.length)},560 ${ys(j,labels.length)}"><title>${esc(medium(records.find(d=>(d.medium_id||medium(d))===mediums[i])))} → ${esc(labels[j])}: ${n} selected texts</title></path>`);}
  return `<div class="source-roles"><span>Medium context</span><span>Exact printed council / claimed-source name</span></div><div class="council-map"><div class="map-scroll" role="region" tabindex="0" aria-label="Attribution map; horizontally scrollable on narrow screens"><svg viewBox="0 0 860 ${height}" role="group" aria-labelledby="map-title map-description"><title id="map-title">Selected text attributions</title><desc id="map-description">${records.length} text records connect ${mediums.length} medium contexts with ${labels.length} printed name strings. Activate a medium or name to filter the message table. The same relations are available in the text table below.</desc>${edges.join('')}${mediums.map((m,i)=>{const row=records.find(d=>(d.medium_id||medium(d))===m),n=records.filter(d=>(d.medium_id||medium(d))===m).length;return `<a class="map-node" href="#messages" data-map-medium="${esc(m)}" aria-label="Filter ${esc(medium(row))}, ${n} selected texts"><circle cx="290" cy="${ys(i,mediums.length)}" r="7"/>${mapLabel(medium(row),270,ys(i,mediums.length)-3,'end',32)}<text class="map-count" x="270" y="${ys(i,mediums.length)+24}" text-anchor="end">${n} selected texts</text></a>`;}).join('')}${labels.map((name,i)=>{const n=records.filter(d=>label(d)===name).length;return `<a class="map-node" href="#messages" data-map-council="${esc(name)}" aria-label="Filter printed name ${esc(name)}, ${n} selected texts"><rect x="554" y="${ys(i,labels.length)-6}" width="12" height="12"/>${mapLabel(name,580,ys(i,labels.length)-3)}<text class="map-count" x="580" y="${ys(i,labels.length)+24}">${n} selected texts</text></a>`;}).join('')}</svg></div><p class="map-help">Select a name to filter its records. On a narrow screen, scroll within the map or use the accessible message table below.</p></div>`;
}

function options(values,selected,display=x=>x){return values.map(v=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(display(v))}</option>`).join('');}
function messageFilters(){const mids=unique(docs().map(d=>d.medium_id||medium(d))).sort(),names=unique(docs().map(label)).sort(),origins=unique(docs().map(textOrigin)).sort();const unknown=(value,values)=>value!=='all'&&!values.includes(value)?`<option value="${esc(value)}" selected>Outside this snapshot: ${esc(value)}</option>`:'';return `<form class="toolbar" id="message-filters"><label class="search">Search the text records<input id="message-query" type="search" value="${esc(state.query)}" placeholder="Title, council, medium or source ID"></label><label>Medium context<select id="message-medium"><option value="all">All mediums</option>${unknown(state.medium,mids)}${options(mids,state.medium,id=>medium(docs().find(d=>(d.medium_id||medium(d))===id)))}</select></label><label>Exact printed label<select id="message-council"><option value="all">All printed names</option>${unknown(state.council,names)}${options(names,state.council)}</select></label><label>Text origin<select id="message-origin"><option value="all">All text origins</option>${unknown(state.origin,origins)}${options(origins,state.origin,human)}</select></label><button class="secondary" id="clear-messages" type="button">Clear filters</button></form>`;}
function filteredDocs(){const q=state.query.trim().toLocaleLowerCase();return docs().filter(d=>(state.medium==='all'||(d.medium_id||medium(d))===state.medium)&&(state.council==='all'||label(d)===state.council)&&(state.origin==='all'||textOrigin(d)===state.origin)&&(!q||[d.source_id,d.title,medium(d),label(d),textOrigin(d)].join(' ').toLocaleLowerCase().includes(q)));}
function messageTable(){const rows=filteredDocs(),pages=Math.max(1,Math.ceil(rows.length/12));state.page=Math.min(state.page,pages);return `<div class="result-summary"><p><strong class="filter-count" id="message-count">${number(rows.length)}</strong> selected text units match. Counts refer to retained editions, not independent sessions or total uploads.</p><button id="export-messages" type="button" class="secondary">Export filtered message metadata</button></div><div class="table-wrap" role="region" tabindex="0" aria-label="Selected council message records"><table class="message-table"><thead><tr><th>Message / source edition</th><th>Medium / exact name</th><th>Text coverage</th><th>Source role & attribution</th></tr></thead><tbody>${rows.slice((state.page-1)*12,state.page*12).map(d=>`<tr><th scope="row">${inspectButton(d.source_id,d.title||d.source_id)}<small>${esc(d.source_id)}</small></th><td>${esc(medium(d))}<small>${esc(label(d))}</small></td><td>${number(d.words)} words<small>${esc(human(textOrigin(d)))}<br>${d.date||d.published_at||d.publication_date?esc(d.date||d.published_at||d.publication_date):'Publication date unreported'}</small></td><td><strong>${esc(human(d.corpus_kind||'Source role unreported'))}</strong><small>${esc(human(d.attribution_basis||d.attribution_scope||d.attribution_status||'Source-level attribution; inspect the record'))}</small><small>${external(d.source_url,'Publisher source')}</small></td></tr>`).join('')||'<tr><td colspan="4">No text records match. Clear the filters to restore the published study.</td></tr>'}</tbody></table></div><div class="pagination"><button class="secondary" data-message-page="${state.page-1}" ${state.page<=1?'disabled':''}>Previous</button><span>Page ${state.page} of ${pages}</span><button class="secondary" data-message-page="${state.page+1}" ${state.page>=pages?'disabled':''}>Next</button></div>`;}
function syncFilters(){const u=new URL(location.href);for(const [key,value]of Object.entries({q:state.query,medium:state.medium,council:state.council,origin:state.origin}))value&&value!=='all'?u.searchParams.set(key,value):u.searchParams.delete(key);history.replaceState(null,'',u);$('#message-results').innerHTML=messageTable();announce(`${filteredDocs().length} message records match the filters.`);}

function comparisonView(){const l=state.analysis.lexical||{},t=state.analysis.topics||{},cl=state.analysis.clusters||{};return `${l.status==='fitted'?`<div class="comparison-controls"><label>Text length comparison<select id="matrix-mode"><option value="whole">Whole selected text</option><option value="window">Centered 300-token spans</option></select></label><button type="button" class="secondary" id="export-matrix">Export complete displayed-mode matrix</button></div><div id="matrix-results">${matrixView()}</div><h3>Closest text pairs</h3><label class="keyword-tools">Compare pair types<select id="pair-kind"><option value="cross">Different mediums</option><option value="same-label">Same printed label, different mediums</option><option value="all">All text pairs</option></select></label><div id="pair-results">${pairView()}</div>`:`<p class="empty">Lexical model: ${esc(human(l.status||'not supplied'))}. No similarity scores are inferred for absent text.</p>`}
    ${sensitivityView()}<h3>Exploratory topics & clusters</h3>${arr(t.components).length?`<div class="topic-list">${t.components.map((c,i)=>`<article class="topic"><span class="micro-label">Factor ${esc(c.id??i+1)}</span><h3>${esc(c.label||'Prominent terms')}</h3><div class="chips">${arr(c.terms).map(x=>`<span>${esc(typeof x==='string'?x:x.term)}</span>`).join('')}</div></article>`).join('')}</div>`:`<p class="empty">Topic model: ${esc(human(t.status||'not supplied'))}. An insufficient corpus remains an analysis limit.</p>`}
    <p class="analysis-note">${esc(t.selection||t.scope||'Topic factors are exploratory descriptions of these texts, not validated doctrines or optimal categories.')} Cluster status: ${esc(human(cl.status||'not supplied'))}${finite(cl.silhouette)?`; cosine silhouette ${number(cl.silhouette,5)}`:''}${finite(cl.medium_ARI)?`; medium-context adjusted Rand index ${number(cl.medium_ARI,3)}`:''}. These values do not measure supernatural truth or independent source agreement.</p>${cl.scope||cl.medium_ARI===1?`<div class="scope-note"><p>${esc(cl.scope||'')}</p>${cl.medium_ARI===1?'<p><strong>The cluster partition exactly matches the medium contexts in this snapshot.</strong> Medium style, source format and claimed-source themes are confounded here; these clusters cannot distinguish their contributions.</p>':''}</div>`:''}
    ${keywordView()}${readingView()}${supplementalReadingsView()}<h3>Research figures</h3><div class="figure-grid">${figuresView()}</div>${retrievalView()}`;}

function sensitivityView(){const l=state.analysis.lexical||{},rows=arr(l.pair_summaries);if(!rows.length)return '';return `<h3>Name-mask sensitivity</h3><p class="analysis-note">${esc(l.mask_rule||'Council and medium names are masked in the declared comparison representation.')} ${esc(l.unmasked_sensitivity||'The unmasked representation is a separately fitted comparison.')} Pair means describe dependent document pairs; no significance or agreement probability is estimated.</p><div class="table-wrap" role="region" tabindex="0" aria-label="Name-mask sensitivity by source pair category"><table><thead><tr><th>Pair category</th><th>Pairs</th><th>Masked mean cosine</th><th>Unmasked mean cosine</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${esc(human(r.category))}</th><td>${number(r.pairs)}</td><td>${number(r.mean_cosine,4)}</td><td>${number(r.mean_unmasked_cosine,4)}</td></tr>`).join('')}</tbody></table></div>`;}

function matrixData(){const l=state.analysis.lexical||{},w=state.matrix==='window';return {ids:arr(w?l.window_300_source_ids:l.source_ids),matrix:arr(w?l.window_300_matrix:l.matrix)};}
function matrixView(){const {ids,matrix}=matrixData();if(!ids.length)return '<p class="empty">No texts satisfy this length rule. Shorter texts are excluded from the window comparison, not padded.</p>';const size=ids.length>40?20:ids.length,blocks=Math.ceil(ids.length/size);state.rowBlock=Math.max(0,Math.min(state.rowBlock,blocks-1));state.colBlock=Math.max(0,Math.min(state.colBlock,blocks-1));const rs=state.rowBlock*size,cs=state.colBlock*size,rows=ids.slice(rs,rs+size),cols=ids.slice(cs,cs+size),order=arr(state.analysis.lexical.source_ids),blockOptions=n=>Array.from({length:blocks},(_,i)=>`<option value="${i}" ${n===i?'selected':''}>${i*size+1}–${Math.min(ids.length,(i+1)*size)}</option>`).join('');
  return `<p class="analysis-note">${number(ids.length)} eligible source texts. ${esc(state.matrix==='window'?(state.analysis.lexical.window_rule||'Centered 300-token spans; shorter texts excluded.'):(state.analysis.lexical.scope||'Whole-text TF-IDF cosine comparison.'))} The message-list filters do not refit this published matrix. Diagonal values compare each text with itself; all values are cosine scores, not percentages.</p>${blocks>1?`<div class="comparison-controls"><label>Visible row positions<select id="matrix-rows">${blockOptions(state.rowBlock)}</select></label><label>Visible column positions<select id="matrix-columns">${blockOptions(state.colBlock)}</select></label></div><p class="caption">Showing rows ${rs+1}–${rs+rows.length} and columns ${cs+1}–${cs+cols.length} of ${ids.length}. Complete CSV export includes every pair.</p>`:''}<div class="matrix-scale" aria-label="Color scale from lower to higher cosine"><b>0 · lower</b>${shades.map(s=>`<span style="background:${s}"></span>`).join('')}<b>higher · 1</b></div><div class="table-wrap" role="region" tabindex="0" aria-label="Council text cosine matrix"><table class="matrix-table"><thead><tr><th>Text unit · source order</th>${cols.map(id=>`<th>${order.indexOf(id)+1}</th>`).join('')}</tr></thead><tbody>${rows.map((id,i)=>`<tr><th scope="row">${inspectButton(id,`${order.indexOf(id)+1}. ${doc(id)?.title||id}`)}</th>${cols.map((col,j)=>{const value=matrix[rs+i]?.[cs+j],shade=finite(value)?Math.min(4,Math.floor(Math.max(0,value)*5)):0;return `<td class="${id===col?'self-cell':''}" style="background:${shades[shade]};color:${shade===4?'#fff':'#202d2a'}">${number(value,3)}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`;
}
function pairRows(){const {ids,matrix}=matrixData(),rows=[];for(let i=0;i<ids.length;i++)for(let j=i+1;j<ids.length;j++){const a=doc(ids[i]),b=doc(ids[j]),value=matrix[i]?.[j];if(!a||!b||!finite(value))continue;const cross=(a.medium_id||medium(a))!==(b.medium_id||medium(b));if(state.pairKind==='cross'&&!cross)continue;if(state.pairKind==='same-label'&&(!cross||label(a)!==label(b)))continue;rows.push({a,b,value});}return rows.sort((a,b)=>b.value-a.value||a.a.source_id.localeCompare(b.a.source_id));}
function pairView(){const rows=pairRows();return `<p class="caption">${number(rows.length)} eligible pairs; showing at most 20 highest scores in the selected whole/window representation. This is retrieval, not verified question or answer equivalence.</p><div class="table-wrap" role="region" tabindex="0" aria-label="Closest council text pairs"><table class="pair-table"><thead><tr><th>First text</th><th>Second text</th><th>Cosine</th><th>Printed-name comparison</th></tr></thead><tbody>${rows.slice(0,20).map(r=>`<tr><th scope="row">${inspectButton(r.a.source_id,r.a.title)}<small>${esc(medium(r.a))} · ${esc(label(r.a))}</small></th><td>${inspectButton(r.b.source_id,r.b.title)}<small>${esc(medium(r.b))} · ${esc(label(r.b))}</small></td><td>${number(r.value,3)}</td><td>${label(r.a)===label(r.b)?'Same printed name':'Different printed names'}<small>No entity-identity or answer-equivalence inference</small></td></tr>`).join('')||'<tr><td colspan="4">No eligible pairs of this type exist in the selected text frame.</td></tr>'}</tbody></table></div>`;}

function keywordView(){const k=state.analysis.keywords||{},keys=Object.keys(k.dictionary||{});if(!keys.length||!arr(k.rows).length)return '';if(!keys.includes(state.keyword))state.keyword=keys[0];return `<h3>Keyword extraction</h3><label class="keyword-tools">Literal keyword dictionary<select id="keyword-name">${options(keys,state.keyword,human)}</select></label><div id="keyword-results">${keywordTable()}</div>`;}
function keywordTable(){const k=state.analysis.keywords||{},rows=arr(k.rows).map(r=>({r,d:doc(r.source_id),v:r.rates?.[state.keyword]})).filter(x=>x.d&&x.v!==undefined).sort((a,b)=>(finite(b.v)?b.v:b.v?.per_1000_tokens??b.v?.per_1000??0)-(finite(a.v)?a.v:a.v?.per_1000_tokens??a.v?.per_1000??0));return `<p class="analysis-note">Literal forms: ${esc(arr(k.dictionary?.[state.keyword]).join(', '))}. Mentions can be quoted, negated or incidental. A keyword hit does not assign a claimed speaker.</p><div class="table-wrap" role="region" tabindex="0" aria-label="Keyword extraction rates"><table class="keyword-table"><thead><tr><th>Text unit</th><th>Medium / printed name</th><th>Matches</th><th>Per 1,000 tokens</th></tr></thead><tbody>${rows.map(({r,d,v})=>`<tr><th scope="row">${inspectButton(r.source_id,d.title)}</th><td>${esc(medium(d))}<small>${esc(label(d))}</small></td><td>${number(r.counts?.[state.keyword]??v?.mentions??v?.count)}</td><td>${number(finite(v)?v:v?.per_1000_tokens??v?.per_1000,3)}</td></tr>`).join('')}</tbody></table></div>`;}
function qualitativeView(){
  const m=state.analysis.reading?.reading_matrix,rows=arr(m?.rows),keys=unique(rows.flatMap(r=>Object.keys(r.cells||{})));
  if(!rows.length)return '';
  if(!keys.includes(state.readingDimension))state.readingDimension=keys[0];
  return `<h3>Compare the practical message</h3><p class="analysis-note">Source recommendations and predictions are presented as claims in the retained texts. These summaries are not endorsed advice, verified events, or numerical good/bad scores. Individual speaker roles and audio alignment remain unverified.</p><div class="comparison-controls"><label>Comparison dimension<select id="reading-dimension">${options(keys,state.readingDimension,key=>key==='recommended_practices'?'Source-recommended practices':human(key))}</select></label><button type="button" class="secondary" id="export-readings">Export all source-reading comparisons</button></div><div id="qualitative-results">${qualitativeTable()}</div>`;
}
function qualitativeTable(){
  const rows=arr(state.analysis.reading?.reading_matrix?.rows);
  return `<div class="table-wrap" role="region" tabindex="0" aria-label="Qualitative comparison of source messages"><table class="qualitative-table"><thead><tr><th>Source edition</th><th>${esc(state.readingDimension==='recommended_practices'?'Source-recommended practices':human(state.readingDimension))} · analyst paraphrase</th></tr></thead><tbody>${rows.map(r=>{const c=r.cells?.[state.readingDimension];return `<tr><th scope="row">${inspectButton(r.source_id,r.title||doc(r.source_id)?.title||r.source_id)}<small>${esc(r.publisher_date||'Publication date unreported')}</small></th><td>${esc(c?.summary||'No supported summary supplied for this dimension.')} ${c?`<details><summary>Inspect source locations</summary><ul class="citation-list">${arr(c.supports).map(s=>`<li>${esc(s.first_turn_id||'Unreported turn')}–${esc(s.last_turn_id||'unreported turn')}: ${number(s.start_seconds,2)}–${number(s.end_seconds,2)} ASR seconds<small>Speaker role: ${esc(s.role||'unknown')} · alignment ${s.audio_alignment_verified===true?'verified':'unverified'}</small><span class="hash">Text SHA-256: ${esc(s.text_artifact_sha256||'unreported')}</span></li>`).join('')}</ul></details>`:''}</td></tr>`;}).join('')}</tbody></table></div>`;
}
function readingView(){const r=state.analysis.reading;const rows=Array.isArray(r)?r:arr(r?.readings||r?.comparisons||r?.records);if(!rows.length)return qualitativeView();return `${qualitativeView()}<h3>Source-reading comparisons</h3><p class="analysis-note">These are analyst-constructed comparison questions and bounded paraphrases, not matched questions verified as spoken in each recording. Reading coverage: ${number(r?.coverage?.documents_read_in_full)} complete texts / ${number(r?.coverage?.asr_words_read)} ASR words. Audio listening: ${r?.coverage?.audio_content_listened===true?'reported':r?.coverage?.audio_content_listened===false?'not performed':'unreported'}; human annotation: ${r?.coverage?.human_annotation===true?'reported':r?.coverage?.human_annotation===false?'not performed':'unreported'}.</p>${rows.map(x=>`<article class="reading-item"><span class="micro-label">${esc(human(x.question_type||'Analyst comparison'))}</span><h3>${esc(x.analyst_question||x.title||x.topic||'Bounded comparison')}</h3><p>${esc(summaryText(x.finding||x.summary||x.interpretation||x.reading))}</p>${x.limits||x.limitations?`<p class="publication-note">${esc(summaryText(x.limits||x.limitations))}</p>`:''}<ul class="citation-list">${arr(x.supports).map(s=>`<li>${inspectButton(s.source_id,doc(s.source_id)?.title||s.source_id)}${finite(s.start_seconds)&&finite(s.end_seconds)?` · recorded ASR interval ${number(s.start_seconds,2)}–${number(s.end_seconds,2)} seconds`:''}<small>${esc(arr(s.turn_ids).join(', '))}${s.audio_alignment_verified===false?' · audio alignment unverified':''}</small></li>`).join('')}</ul><div class="json-links">${arr(x.source_ids).map(id=>inspectButton(id,id)).join('')}</div></article>`).join('')}`;}
function supplementalReadingsView(){const rows=arr(state.analysis.supplemental_readings||state.analysis.reading?.supplemental_readings);if(!rows.length)return '';return `<h3>Galactic sources: bounded reading notes</h3><p class="analysis-note">The coverage below distinguishes complete written-text reading from selected transcript windows. These source-bound observations add interpretation to the retained study texts without adding documents or authenticated speaker identities.</p><div class="supplemental-readings">${rows.map(r=>{const c=r.coverage||{};return `<article class="reading-item" data-reading-source="${esc(r.source_id)}"><span class="micro-label">${esc(human(r.reading_kind))}</span><h3>${inspectButton(r.source_id,r.title||doc(r.source_id)?.title||r.source_id)}</h3><p class="publication-note"><strong>${number(c.words_read)} words read</strong> · ${c.full_document_read===true?'complete text':c.full_document_read===false?'selected spans only':'whole-text coverage unreported'} · ${number(arr(c.spans).length)} reported spans. Human annotation: ${c.human_annotation===true?'reported':c.human_annotation===false?'not performed':'unreported'}; audio listening: ${c.audio_listened===true?'reported':c.audio_listened===false?'not performed':'unreported'}.</p><p class="analysis-note">${esc(r.selection_rule||'Selection rule unreported')}</p>${arr(r.observations).map(o=>`<div class="supplemental-observation"><p>${esc(o.paraphrase||'No observation supplied.')}</p>${o.qualifying_note?`<p class="publication-note">${esc(o.qualifying_note)}</p>`:''}<details><summary>Inspect observation locations</summary><ul class="citation-list">${arr(o.supports).map(s=>`<li>Characters ${number(s.start_character)}–${number(s.end_character)} · ${number(s.words)} span words<small>Speaker role: ${esc(s.role||'unknown')}; audio alignment ${s.audio_alignment_verified===true?'verified':'unverified'}${finite(s.start_seconds)&&finite(s.end_seconds)?`; ASR seconds ${number(s.start_seconds,2)}–${number(s.end_seconds,2)}`:''}</small>${arr(s.turn_ids).length?`<small>${esc(s.turn_ids.join(', '))}</small>`:''}<span class="hash">Span SHA-256: ${esc(s.span_sha256||'unreported')}</span></li>`).join('')}</ul><span class="hash">Text SHA-256: ${esc(r.text_artifact_sha256||'unreported')}</span></details></div>`).join('')}</article>`;}).join('')}</div>`;}

function figuresView(){const fs=arr(state.analysis.figures),shown=fs.filter(f=>/\.(svg|png)$/.test(f.file));const chosen=[...new Map(shown.sort((a,b)=>Number(a.file.endsWith('.svg'))-Number(b.file.endsWith('.svg'))).map(f=>[f.file.replace(/\.(svg|png)$/,''),f])).values()];return chosen.map(f=>{if(!/^[a-zA-Z0-9_.-]+\.(svg|png)$/.test(f.file))return '';const stem=f.file.replace(/\.(svg|png)$/,'');return `<figure class="figure"><h3>${esc(f.title||human(stem))}</h3><p class="figure-open"><a href="figures/${esc(f.file)}" target="_blank" rel="noopener">Open larger figure ↗</a></p><img src="figures/${esc(f.file)}" alt="${esc(f.alt||f.title||stem)}" loading="lazy"><figcaption>${esc(f.alt||f.title||stem)}<div class="figure-links">${fs.filter(x=>x.file.startsWith(stem+'.')&&/^[a-zA-Z0-9_.-]+\.(svg|png|pdf)$/.test(x.file)).map(x=>`<a href="figures/${esc(x.file)}" download>${esc(x.file.split('.').at(-1).toUpperCase())}</a>`).join('')}</div></figcaption></figure>`;}).join('')||'<p class="empty">No analytical figures are supplied for this snapshot.</p>';}
function retrievalView(){const r=state.analysis.lexical_retrieval;if(!r)return '';return `<h3>Mentions in the earlier corpus</h3><p class="analysis-note">${esc(r.scope||'Lexical retrieval in an earlier frozen corpus is a separate discovery layer. Mentions do not become new council-attributed texts.')}</p><p class="caption">${number(r.documents_searched)} earlier text units / ${number(r.words_searched)} words searched; ${number(r.documents_with_hits)} units with at least one query hit.</p><div class="table-wrap" role="region" tabindex="0" aria-label="Prior corpus exact phrase retrieval"><table><thead><tr><th>Exact query phrase</th><th>Texts with a hit</th><th>Occurrences</th></tr></thead><tbody>${arr(r.query_counts).map(q=>`<tr><th scope="row">${esc(q.query)}</th><td>${number(q.documents)}</td><td>${number(q.occurrences)}</td></tr>`).join('')}</tbody></table></div><details><summary>Inspect matching earlier source records</summary><ul class="source-list">${arr(r.hits).map(h=>`<li>${external(h.source_url,h.title||h.source_id)}<small>${esc(h.source_id)} · ${esc(human(h.attribution_status||'Unverified phrase retrieval'))}</small><p>${esc(Object.entries(h.counts||{}).filter(([,n])=>n>0).map(([name,n])=>`${name}: ${n}`).join('; '))}</p></li>`).join('')}</ul><p class="caption">Earlier-corpus matches are not additional texts in the council-study denominator. Zero hits apply only to these phrases and this retained corpus.</p></details>${retrievalContextView(r)}`;}

function retrievalContextView(retrieval){const rows=arr(retrieval.context_reviews);if(!rows.length)return '';return `<h4>Read the mention in context</h4><p class="analysis-note">These bounded context windows qualify the earlier-corpus phrase matches. They are not whole-document readings or additional council-attributed texts. Speaker roles remain unverified. Review coverage: ${number(retrieval.context_review_coverage?.windows_read)} windows / ${number(retrieval.context_review_coverage?.words_in_windows)} words; ${number(retrieval.context_review_coverage?.full_documents_read_for_this_annotation)} full documents read for this annotation.</p><div class="name-findings context-reviews">${rows.map(r=>`<article class="name-finding"><span class="micro-label">${esc(human(r.context_kind||'Bounded context review'))}</span><h4>${external(r.source_url,arr(retrieval.hits).find(h=>h.source_id===r.source_id)?.title||r.source_id)}</h4><p>${esc(r.paraphrase||'No bounded paraphrase supplied.')}</p><p class="caption">${number(r.context_words_read)} words read in this context window · speaker role ${esc(r.role||r.speaker_role||'unknown')}</p><small class="hash">${esc(r.source_id)}</small><details><summary>Inspect context provenance</summary><p class="caption">${esc(r.coverage||'Bounded context window')} ${finite(r.matched_start_character)&&finite(r.matched_end_character)?'Query-match character range: '+number(r.matched_start_character)+'–'+number(r.matched_end_character)+'.':''}</p><p class="caption">Human annotation: ${r.human_annotation===true?'reported':r.human_annotation===false?'not performed':'unreported'} · audio listening: ${r.audio_listened===true?'reported':r.audio_listened===false?'not performed':'unreported'}</p><span class="hash">Text SHA-256: ${esc(r.text_artifact_sha256||'unreported')}</span><br><span class="hash">Context SHA-256: ${esc(r.context_sha256||'unreported')}</span></details></article>`).join('')}</div>`;}

function collectionView(){const a=state.acquisition;if(!a)return '<p class="empty">No acquisition receipt snapshot is available in this view. Audio retained, duration, bytes and transcription totals remain unknown here. The text-study counts above do not imply audio was downloaded.</p>';const s=a.summary||{},rows=arr(a.records);return `<p class="publication-note">Receipt snapshot: ${esc(date(a.generated_at))}. ${esc(a.scope||'Audio provenance is separate from the selected written-message study.')} This page displays a saved snapshot, not live job progress.</p><div class="metrics" aria-label="Recording acquisition coverage"><div><b id="audio-retained">${number(s.completed_publications)}</b><span>retained publication records</span></div><div><b>${number(s.new_audio_downloads)}</b><span>new publisher audio downloads</span></div><div><b>${number(s.reused_audio_publications)}</b><span>previously retained recordings reused</span></div><div><b>${number(finite(s.decoded_duration_seconds)?s.decoded_duration_seconds/3600:null,2)}</b><span>decoded recording hours</span></div></div><div class="scope-note"><p>${number(s.local_asr_completed)} local ASR editions; ${number(s.publisher_caption_linked)} publisher-caption links. Referenced retained audio: ${number(finite(s.retained_bytes)?s.retained_bytes/1e6:null,2)} MB.${finite(s.new_retained_bytes)?' Newly retained: '+number(s.new_retained_bytes/1e6,2)+' MB.':''} Total YouTube uploads: <strong>${number(s.upstream_total_videos)}</strong>.</p><p>Full recordings and transcript bodies remain in the private workspace. YouTube edition equivalence, word accuracy and audio-text alignment require their own evidence. Source discovery, reused media, new downloads and analyzed text are different counts.</p></div><div class="result-summary"><p>${number(rows.length)} acquisition records in this receipt.</p><button id="export-acquisition" type="button" class="secondary">Export audio metadata</button></div><div class="table-wrap" role="region" tabindex="0" aria-label="Council audio acquisition records"><table class="collection-table"><thead><tr><th>Recording</th><th>Collection origin</th><th>Retained duration / bytes</th><th>Text status</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${esc(r.title||r.publication_id)}<small>${esc(r.publisher||r.medium||'Publisher unreported')} · ${esc(r.claimed_label||r.council_label_exact||r.council_label||'Source label unreported')}</small><small>${external(r.source_url,'Publisher source')}</small>${doc(r.document_source_id)?inspectButton(r.document_source_id,'Inspect linked text edition'):''}</th><td>${esc(human(r.acquisition_origin))}<small>${esc(human(r.collection_status))}</small></td><td>${number(finite(r.decoded_duration_seconds)?r.decoded_duration_seconds/60:null,2)} minutes<small>${number(finite(r.retained_bytes)?r.retained_bytes/1e6:null,2)} MB${finite(r.retained_bitrate_bps)?' · '+number(r.retained_bitrate_bps/1000,1)+' kbps':''}${r.channel_transform?'<br>'+esc(line(r.channel_transform)):''}</small></td><td>${r.local_asr_completed===true?'Local ASR completed':r.publisher_caption_linked===true?'Publisher caption linked':esc(human(r.transcript_status||'Text status unreported'))}<small>${finite(r.asr_words)?number(r.asr_words)+' recognized words':'Recognized word count unreported'}<br>YouTube edition: ${esc(human(r.youtube_edition_equivalence||'unverified'))}</small></td></tr>`).join('')||'<tr><td colspan="4">No recording receipts are supplied.</td></tr>'}</tbody></table></div>`;}

function methodsView(){const a=state.analysis;return `<div class="reading-width"><p>${esc(a.method_summary||a.methods?.summary||'The downloadable analysis records the executed lexical model, source coverage, topic and clustering choices, length controls and source bindings. Models describe the observed corpus and do not validate source identity.')}</p></div><ul class="limitations">${arr(a.limitations).map(x=>`<li>${esc(summaryText(x))}</li>`).join('')}</ul>${a.methods?`<details><summary>Inspect the declared analysis methods</summary><pre>${esc(JSON.stringify(a.methods,null,2))}</pre></details>`:''}<div class="json-links"><a href="analysis.json" download>Download complete analysis JSON</a>${state.registers.map(r=>`<a href="${esc(r._public_file)}" download>Download ${r._public_file==='galactic-register.json'?'Galactic':'Contract / Contact'} source register</a>`).join('')}${state.acquisition?'<a href="acquisition.json" download>Download acquisition receipts</a>':''}</div>`;}
function filteredSources(){const q=state.sourceQuery.toLocaleLowerCase().trim();return sources().filter(s=>!q||[sourceId(s),s.title,s.publisher,sourceURL(s),s.medium,s.council_label_exact].join(' ').toLocaleLowerCase().includes(q));}
function sourceList(){const rows=filteredSources(),pages=Math.max(1,Math.ceil(rows.length/15));state.sourcePage=Math.min(state.sourcePage,pages);return `<p class="caption"><strong id="source-count">${number(rows.length)}</strong> source records match. Search results, full publisher bodies and failed requests retain their distinct access states.</p><ul class="source-list">${rows.slice((state.sourcePage-1)*15,state.sourcePage*15).map(s=>`<li>${inspectButton(sourceId(s),s.title||sourceId(s))}<p>${esc(s.publisher||s.medium||'Publisher unreported')}</p><small>${esc(human(s.access_depth||'access depth unreported'))} · ${esc(human(s.retrieval_status||s.status||'retrieval status unreported'))}</small><small>${external(sourceURL(s),'Open source')}</small></li>`).join('')}</ul>${!rows.length?'<p class="empty">No source records match this search. This does not establish that a name is absent elsewhere.</p>':''}<div class="pagination"><button class="secondary" data-source-page="${state.sourcePage-1}" ${state.sourcePage<=1?'disabled':''}>Previous sources</button><span>Page ${state.sourcePage} of ${pages}</span><button class="secondary" data-source-page="${state.sourcePage+1}" ${state.sourcePage>=pages?'disabled':''}>Next sources</button></div>`;}

function inspect(id,trigger){const d=doc(id),s=source(id);if(!d&&!s){announce('This source identifier has no loaded detail record.');return;}const x=d||s;state.returnFocus=trigger;$('#source-detail').innerHTML=`<h2 id="source-title" class="source-title">${esc(x.title||id)}</h2><p>${external(d?.source_url||sourceURL(s),'Open the publisher source')}</p>${facts([['Source identifier',esc(id)],...(s&&sourceId(s)!==id?[['Publisher register source',esc(sourceId(s))],['Edition binding','The declared source/receipt binding links this ASR edition to the publisher record. The register\'s own access state is shown separately.']]:[]),['Medium / publisher',esc(d?medium(d):(s.medium||s.publisher||'Unreported'))],['Exact printed label',esc(d?label(d):(s.council_label_exact||s.claimed_label||'Not assigned from this record'))],['Edition / access',esc(d?human(textOrigin(d)):human(s.access_depth||'unreported'))],['Research-source retrieval',esc(human(s?.retrieval_status||s?.status||(d?'Retained text described by analysis':'unreported')))],...(s?.source_local_attribution?[['Attribution support',esc(human(s.source_local_attribution))]]:[]),...(s?.scope?[['Source scope',esc(line(s.scope))]]:[]),...(s?.primary_for?[['Primary for',esc(line(s.primary_for))]]:[]),...(d?[['Text length',`${number(d.words)} words`],['Text scope',esc(d.text_scope||'Unreported')],['Corpus role',esc(human(d.corpus_kind||'unreported'))],['Source format',esc(human(d.source_format||'unreported'))],['Attribution basis',esc(line(d.attribution_basis||d.attribution_scope||d.attribution_status||d.attribution_note||'Source-level attribution only; no utterance-level speaker identity inferred'))],['Text SHA-256',`<span class="hash">${esc(d.text_sha256||d.text_artifact_sha256||d.text_content_sha256||'Unreported')}</span>`]]:[]),['Date',esc(x.date||x.published_at||x.publication_date||'Unreported')],['Source / content SHA-256',`<span class="hash">${esc(s?.content_hash||s?.sha256||s?.content_sha256||'Unreported in this source record')}</span>`],...(s?.hash_scope?[['Research-source hash scope',esc(s.hash_scope)]]:[]),...(s?.decoded_content?.sha256?[['Decoded source SHA-256',`<span class="hash">${esc(s.decoded_content.sha256)}</span>`]]:[]),...(s?.source_reading?[['Source-record reading coverage',`${number(s.source_reading.words_read)} of ${number(s.source_reading.full_document_words)} text words; ${number(s.source_reading.windows)} selected windows; ${s.source_reading.full_document_read===true?'full document read':'partial reading'}`]]:[])])}${s?.paraphrase||s?.summary?`<h3>Source paraphrase</h3><p>${esc(summaryText(s.paraphrase||s.summary))}</p>`:''}${s?.notes?`<h3>Source qualifications</h3><p>${esc(summaryText(s.notes))}</p>`:''}${d?.notes?`<h3>Text-edition notes</h3><p>${esc(summaryText(d.notes))}</p>`:''}${d?'<div class="scope-note"><p>Full text stays in the private corpus. This metadata record does not establish recognition accuracy, every speaker identity or equivalent answers across sources.</p></div>':''}`;$('#source-dialog').showModal();$('#close-source').focus();}

function csvValue(value){let v=typeof value==='object'&&value!==null?JSON.stringify(value):String(value??'');if(/^[=+\-@]/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"';}
function exportCsv(name,headers,rows){const content='\ufeff'+[headers,...rows].map(r=>r.map(csvValue).join(',')).join('\r\n')+'\r\n',blob=new Blob([content],{type:'text/csv;charset=utf-8'}),href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),1000);announce(`Exported ${rows.length} rows.`);}

document.addEventListener('submit',e=>e.preventDefault());
document.addEventListener('input',e=>{if(e.target.id==='message-query'){state.query=e.target.value;state.page=1;syncFilters();}if(e.target.id==='source-query'){state.sourceQuery=e.target.value;state.sourcePage=1;$('#source-results').innerHTML=sourceList();announce(`${filteredSources().length} source records match.`);}});
document.addEventListener('change',e=>{const key={'message-medium':'medium','message-council':'council','message-origin':'origin'}[e.target.id];if(key){state[key]=e.target.value;state.page=1;syncFilters();}if(e.target.id==='matrix-mode'){state.matrix=e.target.value;state.rowBlock=0;state.colBlock=0;$('#matrix-results').innerHTML=matrixView();$('#pair-results').innerHTML=pairView();announce(`Showing ${state.matrix==='window'?'centered 300-token':'whole-text'} comparisons.`);}if(['matrix-rows','matrix-columns'].includes(e.target.id)){state[e.target.id==='matrix-rows'?'rowBlock':'colBlock']=Number(e.target.value);$('#matrix-results').innerHTML=matrixView();$('#'+e.target.id)?.focus();}if(e.target.id==='pair-kind'){state.pairKind=e.target.value;$('#pair-results').innerHTML=pairView();}if(e.target.id==='keyword-name'){state.keyword=e.target.value;$('#keyword-results').innerHTML=keywordTable();}if(e.target.id==='reading-dimension'){state.readingDimension=e.target.value;$('#qualitative-results').innerHTML=qualitativeTable();announce('Showing '+human(state.readingDimension)+' source comparisons.');}});
document.addEventListener('click',e=>{
  if(e.target.closest('#retry-load')){load();return;}
  const inspection=e.target.closest('[data-inspect]');if(inspection)inspect(inspection.dataset.inspect,inspection);
  if(e.target.closest('#close-source'))$('#source-dialog').close();
  if(e.target.closest('#clear-messages')){Object.assign(state,{query:'',medium:'all',council:'all',origin:'all',page:1});$('#message-filters').outerHTML=messageFilters();syncFilters();$('#message-query').focus();}
  const map=e.target.closest('[data-map-medium],[data-map-council]');if(map){Object.assign(state,{query:'',medium:map.dataset.mapMedium||'all',council:map.dataset.mapCouncil||'all',origin:'all',page:1});$('#message-filters').outerHTML=messageFilters();syncFilters();$('#message-query').focus({preventScroll:true});}
  const page=e.target.closest('[data-message-page]');if(page&&!page.disabled){state.page=Number(page.dataset.messagePage);$('#message-results').innerHTML=messageTable();$('#message-results .pagination button:not(:disabled)')?.focus();}
  const sp=e.target.closest('[data-source-page]');if(sp&&!sp.disabled){state.sourcePage=Number(sp.dataset.sourcePage);$('#source-results').innerHTML=sourceList();$('#source-results .pagination button:not(:disabled)')?.focus();}
  if(e.target.closest('#export-messages')){const keys=['source_id','primary_source_id','title','source_url','medium_id','medium','council_label_exact','text_origin','source_format','corpus_kind','text_scope','attribution_scope','words','text_artifact_sha256','published_at'];exportCsv('council-message-metadata.csv',keys,filteredDocs().map(d=>keys.map(k=>d[k])));}
  if(e.target.closest('#export-matrix')){const {ids,matrix}=matrixData(),rows=[];ids.forEach((id,i)=>ids.forEach((other,j)=>rows.push([id,other,matrix[i]?.[j],id===other])));exportCsv(`council-${state.matrix}-cosine-matrix.csv`,['source_a','source_b','cosine','self_comparison'],rows);}
  if(e.target.closest('#export-readings')){const rows=[];for(const r of arr(state.analysis.reading?.reading_matrix?.rows))for(const [key,c]of Object.entries(r.cells||{}))rows.push([r.source_id,r.title,key,c.summary,c.supports]);exportCsv('council-source-reading-comparisons.csv',['source_id','title','dimension','analyst_paraphrase','source_supports'],rows);}
  if(e.target.closest('#export-acquisition')){const keys=['publication_id','source_id','primary_source_id','document_source_id','publisher','title','source_url','claimed_label','council_label','medium_id','medium_name','acquisition_origin','collection_status','retained_bytes','retained_sha256','retained_bitrate_bps','channel_transform','decoded_duration_seconds','local_asr_completed','asr_words','youtube_edition_equivalence'];exportCsv('council-audio-metadata.csv',keys,arr(state.acquisition?.records).map(r=>keys.map(k=>r[k])));}
});
$('#source-dialog').addEventListener('close',()=>{if(state.returnFocus?.isConnected)state.returnFocus.focus();});
window.addEventListener('hashchange',navCurrent);
load();
